    customers = []

    dep = g(instance, "depot", g(instance, "depot_node", None))
    dep_xy = xy(dep) if dep is not None else None
    coords[depot] = dep_xy if dep_xy is not None else (0.0, 0.0)

    data = g(instance, "customers", g(instance, "nodes", g(instance, "locations", None)))
    if data is not None:
        items = list(data.values()) if isinstance(data, dict) else list(data)
        k = 0
        while k < len(items):
            n = items[k]
            cid = node_id(n, k + 1)
            if cid != depot:
                customers.append(cid)
                demands[cid] = demand_of(n)
                p = xy(n)
                if p is not None:
                    coords[cid] = p
            k += 1
    else:
        n = g(instance, "n_customers", g(instance, "num_customers", 0))
        if n is None:
            n = 0
        dlist = g(instance, "demands", None)
        xs = g(instance, "x", None)
        ys = g(instance, "y", None)
        c = 1
        while c <= int(n):
            customers.append(c)
            if isinstance(dlist, dict):
                demands[c] = int(dlist.get(c, 0))
            elif isinstance(dlist, (list, tuple)) and c < len(dlist):
                demands[c] = int(dlist[c])
            else:
                demands[c] = 0
            if isinstance(xs, (list, tuple)) and isinstance(ys, (list, tuple)) and c < len(xs) and c < len(ys):
                coords[c] = (float(xs[c]), float(ys[c]))
            c += 1

    if not customers:
        return []

    for c in customers:
        if c not in coords:
            coords[c] = (float(c), 0.0)

    if not capacity:
        s = 0
        for c in customers:
            s += demands.get(c, 0)
        capacity = s if s > 0 else 1

    dx0, dy0 = coords[depot]
    def ang_key(c):
        x, y = coords[c]
        dx = x - dx0
        dy = y - dy0
        quad = 0
        if dx < 0 and dy >= 0:
            quad = 1
        elif dx < 0 and dy < 0:
            quad = 2
        elif dx >= 0 and dy < 0:
            quad = 3
        denom = abs(dx) + abs(dy) + 1e-12
        return (quad, dy / denom, dist(depot, c), demands.get(c, 0), c)

    order = sorted(customers, key=ang_key)

    routes = []
    cur = []
    load = 0
    for c in order:
        d = demands.get(c, 0)
        if d > capacity and capacity > 0:
            if cur:
                routes.append(cur)
                cur = []
                load = 0
            routes.append([c])
            continue
        if cur and load + d > capacity:
            routes.append(cur)
            cur = [c]
            load = d
        else:
            cur.append(c)
            load += d
    if cur:
        routes.append(cur)

    fixed = []
    for r in routes:
        fixed.extend(split_by_capacity(r))
    routes = fixed

    i = 0
    while i < len(routes):
        routes[i] = nearest_order(routes[i])
        routes[i] = two_opt(routes[i])
        i += 1

    routes = improve(routes)

    seen = set()
    final_routes = []
    i = 0
    while i < len(routes):
        r = routes[i]
        nr = []
        j = 0
        while j < len(r):
            c = r[j]
            if c not in seen:
                seen.add(c)
                nr.append(c)
            j += 1
        if nr:
            final_routes.append(nr)
        i += 1

    missing = []
    i = 0
    while i < len(customers):
        c = customers[i]
        if c not in seen:
            missing.append(c)
        i += 1

    if missing:
        extra = split_by_capacity(nearest_order(missing))
        i = 0
        while i < len(extra):
            final_routes.append(two_opt(extra[i]))
            i += 1

    return final_routes
